# ! [feature (const_fn)] extern crate extprim ; use extprim :: u128 :: u128 ; pub struct Decimal (u128) ; const DECIMAL_BITS_SIGN : u128 = u128 :: from_parts (0x80000000_00000000 , 0x00000000_00000000) ; impl Decimal { # [doc = " Returns -1 if the decimal is negative, or 1 if it is 0 or positive"] pub fn get_signum_i8 (self) -> i8 { match self . 0 & DECIMAL_BITS_SIGN { DECIMAL_BITS_SIGN => - 1 , _ => 1 } } }